function collectDraft(){const f=$('#plEdit');if(!f)return draft;const v=new FormData(f),split=k=>String(v.get(k)||'').split(/[,，\n]/).map(s=>s.trim()).filter(Boolean);const patch=Object.fromEntries(['name','species','breed','age','gender','neutered','location','bio','food','toy'].map(k=>[k,String(v.get(k)||'').trim()]));draft={...draft,...patch,tags:split('tags'),icebreakers:String(v.get('icebreakers')||'').split('\n').map(s=>s.trim()).filter(Boolean),preferences:{...draft.preferences,...Object.fromEntries(['step_7','step_8','step_9','step_11'].map(k=>[k,split(k)]))}};return draft}

async function saveProfile(){const d=collectDraft();if(!d.name)throw Error('请填写宠物名字。');if(d.tags.length>8)throw Error('个性标签最多 8 个。');if(d.icebreakers.length>3)throw Error('破冰问题最多 3 个。');if(d.tags.some(t=>t.length>20))throw Error('每个标签最多 20 个字。');await window.PawMeetOnline.savePet(petId,d);const version=id();window.PawMeetOnline.cachePet(petId,{petLifeRevision:version});if(allPets().find(p=>pid(p)===petId)?.petLifeRevision!==version)throw Error('资料未能保存，本地空间可能不足；请减少照片后重试。');window.syncUserFromPawMeet?.();window.renderPetCards?.();draftDirty=false;draft=null;screen='profile';render();notice('档案已保存，探索卡片同步更新')}

function preview(){const wasEdit=!!draft;if($('#plEdit'))collectDraft();const p=draft||pet(),safe=Object.fromEntries(Object.entries(p).filter(([,v])=>typeof v==='string').map(([k,v])=>[k,esc(v)]));safe.id=petId;safe.img=esc(p.photos?.[0]||p.avatar);safe.photos=(p.photos||[]).map(esc);safe.tags=(p.tags||[]).map(esc);safe.dist='距离随浏览者位置显示';const html=window.PawMeetExploreCard?.render(safe,0);shell('探索卡片预览',`<div id="plPreview">${wasEdit?'<div class="pl-preview-caption">尚未保存</div>':''}<div class="card-stack-l3"><div class="swipe-card-l3">${html||'预览暂时不可用'}</div></div><div class="action-buttons-l3" aria-hidden="true"><div class="btn-action-l3 btn-pass-l3">${icon('close')}</div><div class="btn-action-l3 btn-like-l3">${icon('heart')}</div></div></div>`,'','pl-preview-body')}

async function imageFile(file,max=1200){if(!file||!file.type.startsWith('image/'))throw Error('请选择图片文件。');if(file.size>12*1024*1024)throw Error('单张照片请小于 12MB。');const src=URL.createObjectURL(file);try{const im=new Image();im.src=src;await im.decode();const canvas=document.createElement('canvas'),scale=Math.min(1,max/Math.max(im.width,im.height));canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.8)}catch(e){throw Error('无法读取这张图片，请换用 JPG 或 PNG。')}finally{URL.revokeObjectURL(src)}}

const commonTypes=[['water','饮水','ml','amount'],['food','主食','g','amount'],['snack','零食','g','amount'],['exercise','运动 / 玩耍','分钟','amount'],['weight','体重','kg','amount'],['poop','排便','','event'],['urine','排尿','','event'],['bath','洗澡','','event'],['deworm','驱虫','','event'],['groom','梳毛 / 护理','','event'],['vaccine','接种疫苗','','event'],['medicine','用药记录','','text']];

function types(){const s=pet().species;let base=commonTypes.map(([id,label,unit,kind])=>({id,label,unit,kind}));if(s==='cat'){base.find(x=>x.id==='poop').label='猫砂盆 · 排便';base.push({id:'litter',label:'换猫砂',unit:'',kind:'event'})}if(['guineapig','rodent'].includes(s))base.find(t=>t.id==='weight').unit='g';if(['rabbit','guineapig','rodent'].includes(s)){base=base.filter(t=>!['bath','snack','vaccine'].includes(t.id));base.push({id:'hay',label:'牧草',unit:'g',kind:'amount'},{id:'greens',label:'蔬菜',unit:'g',kind:'amount'},{id:'clean',label:'笼舍清洁',unit:'',kind:'event'});if(s==='rodent'){base=base.filter(t=>t.id!=='hay');base.push({id:'sand',label:'浴沙更换',unit:'',kind:'event'})}}if(s==='other')base=base.filter(t=>!['bath','vaccine','deworm'].includes(t.id)).concat([{id:'habitat',label:'环境温度',unit:'℃',kind:'number'},{id:'clean',label:'栖居环境清洁',unit:'',kind:'event'}]);return [...base,...data.types]}

const typeFor=r=>r.typeSnapshot||types().find(t=>t.id===r.type)||{label:'历史记录',kind:'text',unit:''};

function weightValue(r){if(!r)return null;const from=typeFor(r).unit,to=types().find(t=>t.id==='weight')?.unit;return from==='g'&&to==='kg'?r.value/1000:from==='kg'&&to==='g'?r.value*1000:r.value}

const metric=(rs,t)=>{const arr=rs.filter(r=>r.type===t&&Number.isFinite(r.value));return arr.length?arr.reduce((s,r)=>s+r.value,0):null};

const number=v=>v==null?'—':Number(v.toFixed(2)).toString();

